import { test, expect } from './fixtures';
import { joinMap } from '../../src/scripts/embedding-map/join';

// Joining the generated map with the project content, as plain data: no page is opened. The map
// is regenerated by hand, so either side can be ahead of the other without breaking the build.

const point = (slug: string) => ({ slug, xyz: [0, 0, 0] });
const project = (slug: string) => ({ slug, title: slug, domain: 'other', featured: false, href: '/#archive' });

test('a project the map does not have yet is left off and reported', () => {
  const joined = joinMap({ projects: [point('a'), point('b')], tools: [] }, [project('a'), project('b'), project('new')]);
  expect(joined.projects.map((p) => p.slug)).toEqual(['a', 'b']);
  expect(joined.missing).toEqual(['new']);
  expect(joined.unknown).toEqual([]);
});

test('a map point whose project is gone is dropped along with its tool links', () => {
  const map = {
    projects: [point('gone'), point('a')],
    tools: [
      { name: 'Shared', projects: ['gone', 'a'], xyz: [0, 0, 0] },
      { name: 'Only gone', projects: ['gone'], xyz: [0, 0, 0] },
    ],
  };
  const joined = joinMap(map, [project('a')]);
  expect(joined.projects).toEqual([{ ...project('a'), xyz: [0, 0, 0] }]);
  expect(joined.tools).toEqual([{ name: 'Shared', projects: [0], xyz: [0, 0, 0] }]);
  expect(joined.unknown).toEqual(['gone']);
  expect(joined.missing).toEqual([]);
});
